/* use of inline function to find minimum out of two integers*/
#include<iostream.h>
#include<conio.h>
inline int min(int a, int b)
{
return a > b ? b : a;
}
int main()
{
cout <<"Minimum out of 25 and 26 is: "<<min(25, 26);
cout <<"\nMinimum out of 23 and 22 is:"<<min(23,22);
getch() ;
return 0;
}

